INSERT INTO changelog (title, body, created_at) VALUES
('Задачі: інструкції гарно розкладені, тексти копіюються однією кнопкою',
'Вікно задачі на компʼютері ширше. Інструкції тепер мають розділи з тонкими роздільниками, акуратні списки, таблиці, жовте виділення для важливого. Кожен текст, який треба вставити в рекламу чи надіслати (основний текст, заголовок, опис, повідомлення), — окремий блок з підписом і кнопкою «Копіювати». Джері пише нові інструкції в такому форматі сам; старі можна попросити: «оформи інструкцію в задачі по-новому». Вручну блок для копіювання — три зворотні лапки ```Підпис, текст, ``` у кінці.',
'2026-11-01 14:00:00');
